"""Write morrow/v2/SOLUTIONS.md: the operator's answer key, generated from canon so it can't drift.

    python -m morrow.canon.solutions
"""

from __future__ import annotations

import json
from pathlib import Path

from . import ciphers, later, layout, people, records

ROOT = Path(__file__).resolve().parents[2]


def main() -> None:
    a = layout.ANCHORS
    rk = ciphers.build_residents_key()
    hashes = json.loads((ROOT / "dashboard" / "private-media" / "hashes.json").read_text())
    L = [
        "# Answer key (SPOILERS: operator only)",
        "",
        "Generated by `python -m morrow.canon.solutions` from the canon. Coordinates are the current",
        "layout (provisional until the real Beta world is laid out).",
        "",
        "| Act | Puzzle | Answer |",
        "| --- | --- | --- |",
        "| 1 | Forum entry | robots.txt -> `/forum-import/`, page source of /game-servers.php -> `showthread.php?t=4471` |",
        "| 1 | Security question | `%s` (Rookery's 2010 intro post). Temporary password shown: `cl-mirror-71e4` |" % records.CLIENT_ACCOUNT["security_answer"],
        "| 1 | Roster / time zones | June +2 (Halifax), patchcord +6 (Manchester), finch and Rookery +1, cairn and Kit 0 |",
        "| 2 | Seed | `bracken` -> Java hash `%d` |" % ciphers.java_string_hash("bracken"),
        "| 3 | June's folder | user `juni_lantern`, password `sambro` (lamp flashes Fl W 5s = Sambro Island Light) |",
        "| 3 | Morrow's name | LogBlock: player `morrow` placed glass at June's tower 04:11-04:16 on 2011-05-18 |",
        "| 3 | Inserted resident | the tally book has a `lowpath` row; cairn's real chests don't |",
        "| 4 | Unmask Theo | file any two of: `Lot 14`, `CHI-07`, `2014-12-14`, `waived` |",
        "| 5 | patchcord's folder | user `patchcord`, password `%s` (bass-line note names) |" % ciphers.TUNE_WORD.lower(),
        "| 5 | Recording | ask the desk for `moss_0518.ogg` (the filename is in the replay and the server log) |",
        "| 5 | Rookery's floor | plaintext `%s` (md5 `%s`) |" % (ciphers.FLOOR_PLAINTEXT, ciphers.md5(ciphers.FLOOR_PLAINTEXT)),
        "| 5 | Slipped hands | `%s` -> `%s` (UK layout) |" % (ciphers.build_slipped_line(), ciphers.PATCHCORD_INTENDED),
        "| 5 | Finch's lock | levers ON where the bit is 1: `%s` (left to right) |" % later.FINCH_LOCK_BITS,
        "| 6 | Theo's restart | file `06:44:10` plus `CHI-07/mrrw` or `mid-session` |",
        "| 6 | TCAdmin login | `rookery` / `cl-mirror-71e4` |",
        "| 6 | Hidden original | panel_ok.jpg's EXIF thumbnail shows the 'Start service' confirmation |",
        "| 7 | Braille shelves | `%s` |" % ciphers.BRAILLE_MESSAGE,
        "| 7 | Iona's key chest | %s (3 down, 4 toward spawn from the old dock at %s) |" % (a["iona_key_chest"], a["june_old_dock"]),
        "| 7 | Iona's key | `%s` (md5 `%s`) |" % (ciphers.IONA_TOKEN, ciphers.md5(ciphers.IONA_TOKEN)),
        "| 7 | Annex wall | `%s` |" % ciphers.HALT_COMMAND,
        "| 7 | Flags | `K` + `%s` |" % later.FLAG_WORD,
        "| 8 | Where Morrow learned 'turn it off' | ask the desk; Kit's email, 2019-03-02 |",
        "| 8 | Theo's box | user `tvale`, password `%s` |" % later.TVALE_BOX["password"],
        "| 8 | cairn's room | step on the lot plate, open + close the hinge tin, white dye on the returns chest, flip the lamp lever off |",
        "| 8 | Sound replay | `%s` (FTP: /incoming/MIC-5-18-B.WAV) |" % ciphers.SOUND_REPLAY_FILENAME,
        "| 8 | Dust corridor | `%s` |" % ciphers.LIGHT_CORRIDOR_MESSAGE,
        "| 8 | The bed | put a bed inside lowpath's place at %s; works from Act 9 (before that Morrow tidies it away) |" % (a["lowpath_place"],),
        "| 9 | Clean backup MD5 | `%s` (/ftp/notrecovery/) |" % hashes["notrecovery-mossfield_2011-04-20.zip"],
        "| 9 | Residents' Key | keys `%s` then `%s` -> `%s` |" % (rk["key1"], rk["key2"], ciphers.RESIDENTS_PLAINTEXT),
        "| 9 | Case brief | restart `2011-05-18 06:44:10`, lowpath `2016-08-03`, Kit `2019-03-02`, clean MD5, the player's backdated join date |",
        "| 10 | Ready | MAINT sign at %s reads `MAINT ON` and is waxed, and lowpath's session ended |" % (a["maint_sign"],),
        "| 10 | Console | command `%s`, key = Iona's key, pick what to retain, then type the code in chat at the annex %s |" % (ciphers.HALT_COMMAND, a["maintenance_annex"]),
        "",
        "Residents' passwords in join order: " + ", ".join("%s=%s" % (r.handle, r.lwc_password) for r in people.join_order()),
        "",
    ]
    (ROOT / "morrow" / "v2" / "SOLUTIONS.md").write_text("\n".join(L), encoding="utf-8")
    print("wrote morrow/v2/SOLUTIONS.md")


if __name__ == "__main__":
    main()
